            accept: [['^which'], ['east|west'], ['runs?|ran|crosses|crossed|stretches|stretched|goes|went|leads|led']],
            reject: [{ re: 'left|right|top|bottom', hint: 'A map report never says left or right. Use the compass.' }, { re: '^who', hint: 'This relative word is for people. A road is a thing.' }, { re: 'north|south', hint: 'Follow the road from the river. Which edge of the map does it reach?' }, { re: '^that', hint: 'After a comma, a relative clause that adds extra information about a thing starts with a different relative word.' }, { re: '(river|west|western edge|western side) to the west|from the east(ern)? (edge|side)( of the town)? to the east', hint: 'Follow the road from the river. It cannot start and end on the same side.' }],
